        builder.setBlock(entry);
        auto* c1 = builder.createConstInt(7);
        auto* call_inst = builder.createExprOp(QoreIROpcode::CallIndirect, *call_ref_holder, {c1->result});
        builder.createReturn(call_inst->result);

